"use strict";

// An unrelated helper that this package never publishes. It is SAFE, it is
// a plain function DECLARATION, and it is never reassigned -- so nothing
// about RWF-013/RWF-013b's reassignment refusal has anything to say about
// it. Its only relationship to the export below is that the two happen to
// spell the same word, which is precisely the point: a public export name
// is not provenance for a local symbol (RWF-011).
function parse(input) {
  return "safe:" + String(input);
}

// The real implementation, held behind a property of a local object. This
// analyzer models no value flow through object properties, so
// `registry.impl` is an expression it cannot resolve -- and must therefore
// leave unresolved rather than guess.
const registry = {
  impl: require("./lib/parse"),
};

// The package's documented entry point, and the export a rule names. At
// runtime this holds lib/parse.js's function, NOT the declaration above.
exports.parse = registry.impl;

// The same function object, published under a second name for callers that
// want to be explicit. Statically resolvable via RWF-004a, unlike the
// property access above.
exports.parseSync = require("./lib/parse");
